graphql.query:
query SearchRestaurants($input: SearchRestaurantsDto!) {
  searchRestaurants(input: $input) {
    total
    cached
    results {
      id
      name
      city
      address
      country
      longitude
      latitude
    }
    error { message code }
  }
}

