query Recommendations($limit: Int) {
  recommendations(limit: $limit) {
    cached
    reorder {
      id
      name
      city
    }
    discover {
      id
      name
      city
    }
    error { message code }
  }
}

query Recommendations {
  recommendations(limit: 5) {
    reorder { name }
    error { message code }
  }
}
